INSERT INTO public.questoes (id, material_id, enunciado, referencia, comentario_professor, ordem, publicado) VALUES
('a5329ce4-6666-4f44-90e8-f84928520fb9', '0d0fec83-707e-4f35-b90b-61f7823650ce', 'O Estado do Rio Grande do Sul é representado no Senado Federal por ______ senadores, os quais são eleitos para um mandato de ______ anos, cuja eleição observa o sistema ____________. Assinale a alternativa que preenche, correta e respectivamente, as lacunas do trecho acima.', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2026 / Prefeitura de Pontão - RS / Advogado / Questão: 35', 'A alternativa correta corresponde ao art. 46, caput e §1º, da CF, segundo o qual o Senado Federal compõe-se de representantes dos Estados e do Distrito Federal, eleitos pelo princípio majoritário, cabendo a cada Estado e ao Distrito Federal eleger "três Senadores, com mandato de oito anos"; as demais alternativas estão erradas por trazerem número de senadores, duração de mandato ou sistema eleitoral incompatíveis com o texto constitucional.', 1, true),
('a2b25530-4b42-4b06-b36c-d7e9e7d9b086', '0d0fec83-707e-4f35-b90b-61f7823650ce', 'De acordo com a CF/1988, analise as sentenças abaixo: A Câmara dos Deputados compõe-se de representantes do povo, eleitos pelo sistema majoritário em cada Estado, em cada Território e no Distrito Federal (1ª parte). O Poder Legislativo Federal é exercido pelo Congresso Nacional e cada legislatura terá a duração de 4 anos (2ª parte). O Senado Federal será eleito pelo sistema proporcional, e cada senador será eleito para um mandato de 8 anos (3ª parte). Quais partes estão corretas?', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2026 / Câmara de Cordilheira Alta Camara de Cordilheira Alta - SC / Procurador Legislativo / Questão: 27', 'Apenas a segunda parte está correta, pois o art. 44, parágrafo único, da CF estabelece que "cada legislatura terá a duração de quatro anos"; a primeira parte está errada porque, nos termos do art. 45, caput, a Câmara dos Deputados é eleita pelo sistema proporcional, e não majoritário; e a terceira parte está errada porque, conforme o art. 46, caput, o Senado Federal é eleito pelo princípio majoritário, e não proporcional, de modo que apenas a inversão dos sistemas eleitorais entre as duas Casas torna as partes 1 e 3 incorretas.', 2, true),
('b6d96832-1ffc-4c7c-96d9-2b348d56dc8b', '0d0fec83-707e-4f35-b90b-61f7823650ce', 'Conforme a Constituição Federal, o Deputado ou o Senador perderão o mandato nos seguintes casos, EXCETO:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2025 / Prefeitura de Restinga Seca - RS / Auxiliar - Área: Escola / Questão: 32', 'A alternativa correta é a que não encontra correspondência no art. 55 da CF, pois a mera apresentação de proposta legislativa declarada inconstitucional pelo STF não é causa de perda de mandato parlamentar, tratando-se do exercício regular da função legislativa; as demais alternativas correspondem, respectivamente, ao art. 55, III (falta às sessões), IV (perda de direitos políticos), VI (decretação pela Justiça Eleitoral) e VI, in fine (condenação criminal transitada em julgado).', 3, true),
('edc95516-0ec8-495b-8d10-dd85a0cd2b03', '0d0fec83-707e-4f35-b90b-61f7823650ce', 'Conforme a Constituição Federal, assinale a alternativa que NÃO é competência privativa ao Senado Federal.', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2025 / Prefeitura de Restinga Seca - RS / Auxiliar - Área: Escola / Questão: 31', 'A alternativa correta é a que não é competência do Senado Federal, pois autorizar, por dois terços de seus membros, a instauração de processo contra o Presidente e o Vice-Presidente da República e os Ministros de Estado é competência privativa da Câmara dos Deputados, nos termos do art. 51, I, da CF; as demais alternativas correspondem a competências privativas do Senado Federal previstas no art. 52, incisos IX (letra "a"), VI (letra "b"), V (letra "c") e IV (letra "e").', 4, true),
('7a6e08ec-47f8-4024-99bf-3c07b74fad66', '0d0fec83-707e-4f35-b90b-61f7823650ce', 'Conforme a Constituição Federal, é competência privativa da Câmara dos Deputados:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2024 / Instituto de Previdência dos Servidores Públicos de Esteio PREV ESTEIO - RS / Gestor - Área: Financeiro / Questão: 13', 'A alternativa correta reproduz o art. 51, I, da CF, que atribui privativamente à Câmara dos Deputados "autorizar, por dois terços de seus membros, a instauração de processo contra o Presidente e o Vice-Presidente da República e os Ministros de Estado"; as demais alternativas correspondem, na realidade, a competências privativas do Senado Federal, previstas no art. 52, incisos VIII (letra "a"), XII (letra "b"), IV (letra "c") e X (letra "d").', 5, true),
('3aca5ab3-3c43-4e4f-9465-c59157ee1548', '0d0fec83-707e-4f35-b90b-61f7823650ce', 'Segundo a Constituição Federal vigente, o Congresso Nacional é composto pelo(a): I. Câmara de Deputados.II. Senador Federal.III. Supremo Tribunal Federal. Quais estão corretas?', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2023 / Prefeitura de Maçambará Prefeitura de Macambara - RS / Motorista / Questão: 23', 'Os itens I e II estão corretos, pois o art. 44 da CF estabelece que o Poder Legislativo é exercido pelo Congresso Nacional, composto pela Câmara dos Deputados e pelo Senado Federal; o item III está incorreto porque o Supremo Tribunal Federal é órgão do Poder Judiciário, nos termos do art. 92, I, da CF, e não integra o Congresso Nacional, de modo que apenas os itens I e II estão corretos.', 6, true),
('474e296d-ff13-4a77-815a-5fd2a8dd433d', '0d0fec83-707e-4f35-b90b-61f7823650ce', 'Em certas hipóteses, a Constituição Federal prevê que o Congresso Nacional deve se reunir, em sessão conjunta, dentre as quais NÃO figura:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2022 / Instituto de Assistência à Saúde dos Servidores Públicos do Rio Grande do Sul IPE SAUDE RS - RS / Analista de gestão em Saúde - Área: Direito / Questão: 58', 'A alternativa correta é a que aponta a eleição de membros do Conselho da República, pois essa não é uma hipótese de sessão conjunta prevista no art. 57, §3º, da CF; conforme o art. 89, VII, os membros do Conselho da República que representam o Legislativo são eleitos separadamente, sendo dois pelo Senado Federal e dois pela Câmara dos Deputados, e não pelo Congresso Nacional reunido em sessão conjunta; as demais alternativas correspondem exatamente aos incisos I, II e IV do art. 57, §3º.', 7, true);
