('b6d96832-1ffc-4c7c-96d9-2b348d56dc8b', 'A', 'Deixar de comparecer, em cada sessão legislativa, à terça parte das sessões ordinárias da Casa a que pertencer, salvo licença ou missão por esta autorizada.', false, 0),
('b6d96832-1ffc-4c7c-96d9-2b348d56dc8b', 'B', 'Perder ou tiver suspensos os direitos políticos.', false, 1),
('b6d96832-1ffc-4c7c-96d9-2b348d56dc8b', 'C', 'For decretado pela Justiça Eleitoral, nos casos previstos nesta Constituição.', false, 2),
('b6d96832-1ffc-4c7c-96d9-2b348d56dc8b', 'D', 'Sofrer condenação criminal em sentença transitada em julgado.', false, 3),
('b6d96832-1ffc-4c7c-96d9-2b348d56dc8b', 'E', 'Apresentar proposta legislativa que seja declarada inconstitucional pelo Supremo Tribunal Federal.', true, 4),
('edc95516-0ec8-495b-8d10-dd85a0cd2b03', 'A', 'Estabelecer limites globais e condições para o montante da dívida mobiliária dos Estados, do Distrito Federal e dos Municípios.', false, 0),
('edc95516-0ec8-495b-8d10-dd85a0cd2b03', 'B', 'Fixar, por proposta do Presidente da República, limites globais para o montante da dívida consolidada da União, dos Estados, do Distrito Federal e dos Municípios.', false, 1),
('edc95516-0ec8-495b-8d10-dd85a0cd2b03', 'C', 'Autorizar operações externas de natureza financeira, de interesse da União, dos Estados, do Distrito Federal, dos Territórios e dos Municípios.', false, 2),
('edc95516-0ec8-495b-8d10-dd85a0cd2b03', 'D', 'Autorizar, por dois terços de seus membros, a instauração de processo contra o Presidente e o Vice-Presidente da República e os Ministros de Estado.', true, 3),
('edc95516-0ec8-495b-8d10-dd85a0cd2b03', 'E', 'Aprovar previamente, por voto secreto, após arguição em sessão secreta, a escolha dos chefes de missão diplomática de caráter permanente.', false, 4),
('7a6e08ec-47f8-4024-99bf-3c07b74fad66', 'A', 'Dispor sobre limites e condições para a concessão de garantia da União em operações de crédito externo e interno.', false, 0),
('7a6e08ec-47f8-4024-99bf-3c07b74fad66', 'B', 'Aprovar, por maioria absoluta e por voto secreto, a exoneração, de ofício, do Procurador-Geral da República antes do término de seu mandato.', false, 1),
('7a6e08ec-47f8-4024-99bf-3c07b74fad66', 'C', 'Aprovar previamente, por voto secreto, após arguição em sessão secreta, a escolha dos chefes de missão diplomática de caráter permanente.', false, 2),
('7a6e08ec-47f8-4024-99bf-3c07b74fad66', 'D', 'Suspender a execução, no todo ou em parte, de lei declarada inconstitucional por decisão definitiva do Supremo Tribunal Federal.', false, 3),
('7a6e08ec-47f8-4024-99bf-3c07b74fad66', 'E', 'Autorizar, por dois terços de seus membros, a instauração de processo contra o Presidente e o Vice-Presidente da República e os Ministros de Estado.', true, 4),
('3aca5ab3-3c43-4e4f-9465-c59157ee1548', 'A', 'Apenas I.', false, 0),
